            gen(state, (unsigned long) (p.stage_bytes == 8 ? gadget_vex_ld_amd64_8 : gadget_vex_ld_amd64_4));
            gen(state, meta);
            gen(state, disp);
            gen(state, (unsigned long) next_ip);
