            extern void gadget_amd64_hybrid_mov_reg_reg(void);
            gen_amd64_ensure_reg_cache(state);
            gen(state, (unsigned long) gadget_amd64_hybrid_mov_reg_reg);
            gen(state, packed | ((unsigned long) size << 8));
